import React from 'react';

/**
 * TradePlanCard — Displays a complete TradePlan generated by COMPASS agent.
 *
 * Requirements (Section 5):
 * - Symbol and direction
 * - Timeframe
 * - Thesis
 * - Entry trigger/zone
 * - Stop and invalidation
 * - Targets (T1, T2, runner)
 * - Position size and risk amount
 * - Reward:risk
 * - Event risks
 * - Bull case & Bear case
 * - Confidence & model-estimated badges
 * - Sources chips
 * - Sentinel verdict
 * - Approve / Modify / Reject buttons
 * - The Approve button must be disabled until SENTINEL returns APPROVE or MODIFY.
 * - A VETO must clearly explain why.
 */
export default function TradePlanCard({
  plan,
  sentinelVerdict,
  onApprove,
  onModify,
  onReject,
  onSendToChart
}) {
  if (!plan) {
    return (
      <div style={{
        background: 'rgba(15, 23, 42, 0.65)',
        border: '1px dashed rgba(255, 255, 255, 0.15)',
        borderRadius: '6px',
        padding: '28px',
        textAlign: 'center',
        color: 'var(--text-muted)',
        fontFamily: 'var(--font-data)',
        fontSize: '12px'
      }}>
        NO TRADE PLAN SELECTED · ISSUE COMMAND "Plan a swing trade in AAPL" OR SELECT A TEMPLATE
      </div>
    );
  }

  const isLong = (plan.direction || 'long').toLowerCase() === 'long';
  const verdict = sentinelVerdict?.verdict || plan.sentinel_verdict || 'pending';
  const verdictColor = verdict === 'approve' ? 'var(--neon-green)' : verdict === 'modify' ? 'var(--neon-amber)' : verdict === 'veto' ? 'var(--neon-red)' : '#94a3b8';
  const isApproveDisabled = verdict === 'veto' || verdict === 'pending';

  const rrRatio = plan.reward_risk || plan.rewardRisk;
  const rrColor = rrRatio >= 2.0 ? 'var(--neon-green)' : rrRatio >= 1.5 ? 'var(--neon-amber)' : 'var(--neon-red)';

  const entryPrice = plan.entry?.price || plan.entryPrice;
  const stopPrice = plan.stop?.price || plan.stopLoss;
  const positionQty = plan.position_size?.quantity || plan.positionSize;
  const riskAmount = plan.position_size?.risk_amount || plan.riskAmount;

  return (
    <div style={{
      background: 'rgba(10, 15, 29, 0.90)',
      backdropFilter: 'blur(16px)',
      border: '1px solid rgba(0, 240, 255, 0.25)',
      borderRadius: '8px',
      padding: '18px 22px',
      position: 'relative',
      overflow: 'hidden',
      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.5), inset 0 0 20px rgba(0, 240, 255, 0.04)'
    }}>
      {/* 1. Header Bar: Symbol, Direction, Timeframe, ID, Status */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        borderBottom: '1px solid rgba(255, 255, 255, 0.08)',
        paddingBottom: '12px',
        marginBottom: '14px'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span style={{
            fontSize: '20px',
            fontWeight: 800,
            fontFamily: 'var(--font-display)',
            letterSpacing: '1.2px',
            color: '#ffffff'
          }}>
            {plan.symbol || '—'}
          </span>

          <span style={{
            background: isLong ? 'rgba(34, 197, 94, 0.15)' : 'rgba(239, 68, 68, 0.15)',
            border: `1px solid ${isLong ? 'var(--neon-green)' : 'var(--neon-red)'}`,
            color: isLong ? 'var(--neon-green)' : 'var(--neon-red)',
            fontSize: '10px',
            fontWeight: 800,
            fontFamily: 'var(--font-data)',
            padding: '2px 8px',
            borderRadius: '3px',
            textTransform: 'uppercase',
            letterSpacing: '0.8px'
          }}>
            {isLong ? '▲ LONG' : '▼ SHORT'}
          </span>

          <span style={{
            background: 'rgba(0, 240, 255, 0.1)',
            border: '1px solid rgba(0, 240, 255, 0.3)',
            color: 'var(--neon-cyan)',
            fontSize: '10px',
            fontFamily: 'var(--font-data)',
            padding: '2px 8px',
            borderRadius: '3px',
            textTransform: 'uppercase'
          }}>
            {plan.timeframe || 'SWING'}
          </span>

          <span style={{
            background: 'rgba(255, 255, 255, 0.06)',
            color: 'var(--text-muted)',
            fontSize: '10px',
            fontFamily: 'var(--font-data)',
            padding: '2px 6px',
            borderRadius: '3px'
          }}>
            {plan.asset_class?.toUpperCase() || 'EQUITY'}
          </span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <span style={{ fontSize: '10.5px', color: 'var(--text-muted)', fontFamily: 'var(--font-data)' }}>
            CONFIDENCE: <strong style={{ color: 'var(--neon-cyan)' }}>{Math.round((plan.confidence || 0.7) * 100)}%</strong>
          </span>
          <span style={{
            fontSize: '8px',
            fontFamily: 'var(--font-data)',
            background: 'rgba(168, 85, 247, 0.15)',
            border: '1px solid rgba(168, 85, 247, 0.4)',
            color: '#c084fc',
            padding: '1px 5px',
            borderRadius: '2px'
          }}>
            MODEL-ESTIMATED
          </span>
        </div>
      </div>

      {/* 2. Sentinel Verdict Alert Box */}
      <div style={{
        background: verdict === 'approve' ? 'rgba(34, 197, 94, 0.1)' : verdict === 'modify' ? 'rgba(234, 179, 8, 0.1)' : 'rgba(239, 68, 68, 0.12)',
        border: `1px solid ${verdictColor}`,
        borderRadius: '6px',
        padding: '10px 14px',
        marginBottom: '14px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between'
      }}>
        <div>
          <div style={{
            color: verdictColor,
            fontFamily: 'var(--font-data)',
            fontWeight: 800,
            fontSize: '11px',
            letterSpacing: '0.8px',
            textTransform: 'uppercase'
          }}>
            🛡️ SENTINEL RISK OFFICER VERDICT: {verdict.toUpperCase()}
          </div>
          <div style={{ color: '#e2e8f0', fontSize: '11.5px', marginTop: '3px', lineHeight: '1.4' }}>
            {sentinelVerdict?.reason || plan.sentinel_notes || 'Risk review complete. Strict boundaries enforced.'}
          </div>
          {sentinelVerdict?.required_changes?.length > 0 && (
            <div style={{ color: 'var(--neon-amber)', fontSize: '10.5px', marginTop: '4px', fontFamily: 'var(--font-data)' }}>
              Required Changes: {sentinelVerdict.required_changes.join(' · ')}
            </div>
          )}
        </div>
        <div style={{
          fontSize: '9px',
          fontFamily: 'var(--font-data)',
          color: 'var(--text-muted)',
          textAlign: 'right'
        }}>
          GATED STATUS<br />
          <strong style={{ color: verdictColor }}>{verdict.toUpperCase()}</strong>
        </div>
      </div>

      {/* 3. Core Thesis */}
      <div style={{ marginBottom: '14px' }}>
        <div style={{ fontSize: '10px', color: 'var(--text-muted)', textTransform: 'uppercase', marginBottom: '4px', fontFamily: 'var(--font-data)' }}>
          Trade Thesis · COMPASS Specialist Agent
        </div>
        <div style={{
          fontSize: '12px',
          color: '#f1f5f9',
          lineHeight: '1.5',
          background: 'rgba(255, 255, 255, 0.02)',
          borderLeft: '2px solid var(--neon-cyan)',
          padding: '8px 12px',
          borderRadius: '0 4px 4px 0'
        }}>
          {plan.thesis || '—'}
        </div>
      </div>

      {/* 4. Numbers Grid: Entry, Stop, Targets, R:R */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(4, 1fr)',
        gap: '10px',
        background: 'rgba(0, 0, 0, 0.35)',
        border: '1px solid rgba(255, 255, 255, 0.06)',
        borderRadius: '6px',
        padding: '12px',
        marginBottom: '14px'
      }}>
        {/* Entry */}
        <div>
          <div style={{ fontSize: '9px', color: 'var(--text-muted)', textTransform: 'uppercase', fontFamily: 'var(--font-data)' }}>
            Entry Trigger
          </div>
          <div style={{ fontSize: '17px', fontWeight: 800, color: 'var(--neon-cyan)', fontFamily: 'var(--font-data)', marginTop: '2px' }}>
            {entryPrice ? `$${parseFloat(entryPrice).toFixed(2)}` : '—'}
          </div>
          <div style={{ fontSize: '9px', color: 'var(--text-muted)', marginTop: '2px' }}>
            {plan.entry?.trigger ? plan.entry.trigger.slice(0, 30) + '...' : 'On confirmation'}
          </div>
        </div>

        {/* Stop Loss */}
        <div>
          <div style={{ fontSize: '9px', color: 'var(--neon-red)', textTransform: 'uppercase', fontFamily: 'var(--font-data)' }}>
            Stop Loss (SL)
          </div>
          <div style={{ fontSize: '17px', fontWeight: 800, color: 'var(--neon-red)', fontFamily: 'var(--font-data)', marginTop: '2px' }}>
            {stopPrice ? `$${parseFloat(stopPrice).toFixed(2)}` : '—'}
          </div>
          <div style={{ fontSize: '9px', color: 'var(--text-muted)', marginTop: '2px' }}>
            Risk: {riskAmount ? `$${parseFloat(riskAmount).toFixed(0)}` : '—'} ({positionQty || '—'} shs)
          </div>
        </div>

        {/* Target 1 / 2 */}
        <div>
          <div style={{ fontSize: '9px', color: 'var(--neon-green)', textTransform: 'uppercase', fontFamily: 'var(--font-data)' }}>
            Target 1 (T1)
          </div>
          <div style={{ fontSize: '17px', fontWeight: 800, color: 'var(--neon-green)', fontFamily: 'var(--font-data)', marginTop: '2px' }}>
            {plan.targets?.[0]?.price ? `$${parseFloat(plan.targets[0].price).toFixed(2)}` : '—'}
          </div>
          <div style={{ fontSize: '9px', color: 'var(--text-muted)', marginTop: '2px' }}>
            {plan.targets?.[0]?.rationale || 'Target objective'}
          </div>
        </div>

        {/* Reward:Risk */}
        <div>
          <div style={{ fontSize: '9px', color: rrColor, textTransform: 'uppercase', fontFamily: 'var(--font-data)' }}>
            Reward : Risk
          </div>
          <div style={{ fontSize: '17px', fontWeight: 800, color: rrColor, fontFamily: 'var(--font-data)', marginTop: '2px' }}>
            {rrRatio ? `${rrRatio}R` : '—'}
          </div>
          <div style={{ fontSize: '9px', color: 'var(--text-muted)', marginTop: '2px' }}>
            {rrRatio >= 1.5 ? '✓ Meets min 1.5R' : '⚠ Below 1.5R'}
          </div>
        </div>
      </div>

      {/* 5. Invalidation & Bull/Bear Cases */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: '1fr 1fr',
        gap: '12px',
        marginBottom: '14px',
        fontSize: '11px'
      }}>
        {/* Invalidation */}
        <div style={{
          background: 'rgba(239, 68, 68, 0.05)',
          border: '1px solid rgba(239, 68, 68, 0.2)',
          borderRadius: '5px',
          padding: '10px'
        }}>
          <div style={{ color: 'var(--neon-red)', fontWeight: 800, fontFamily: 'var(--font-data)', marginBottom: '4px', fontSize: '10px' }}>
            🛑 THESIS INVALIDATION (COMPASS MANDATORY)
          </div>
          <div style={{ color: '#cbd5e1', lineHeight: '1.4' }}>
            {plan.invalidation?.condition || plan.what_proves_thesis_wrong?.[0] || 'Daily close below stop level.'}
          </div>
          <div style={{ fontSize: '9px', color: 'var(--text-muted)', marginTop: '4px', fontFamily: 'var(--font-data)' }}>
            Source: {plan.invalidation?.source || 'compass:technical-invalidation'}
          </div>
        </div>

        {/* Bull & Bear Scenarios */}
        <div style={{
          background: 'rgba(255, 255, 255, 0.02)',
          border: '1px solid rgba(255, 255, 255, 0.08)',
          borderRadius: '5px',
          padding: '10px'
        }}>
          <div style={{ color: 'var(--neon-cyan)', fontWeight: 800, fontFamily: 'var(--font-data)', marginBottom: '4px', fontSize: '10px' }}>
            ⚖️ BULL CASE VS. BEAR CASE
          </div>
          <div style={{ color: '#cbd5e1', lineHeight: '1.3', fontSize: '10.5px' }}>
            <div><strong style={{ color: 'var(--neon-green)' }}>Bull:</strong> {plan.bull_case || '—'}</div>
            <div style={{ marginTop: '3px' }}><strong style={{ color: 'var(--neon-red)' }}>Bear:</strong> {plan.bear_case || '—'}</div>
          </div>
        </div>
      </div>

      {/* 6. Event Risks & Source Chips */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        flexWrap: 'wrap',
        gap: '8px',
        marginBottom: '16px'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '6px', flexWrap: 'wrap' }}>
          <span style={{ fontSize: '9px', color: 'var(--text-muted)', fontFamily: 'var(--font-data)' }}>
            SOURCES:
          </span>
          {(plan.sources || ['finnhub:live', 'compass:planner']).map((src, i) => (
            <span
              key={i}
              style={{
                fontSize: '8.5px',
                fontFamily: 'var(--font-data)',
                background: 'rgba(255, 255, 255, 0.05)',
                border: '1px solid rgba(255, 255, 255, 0.1)',
                padding: '1px 6px',
                borderRadius: '2px',
                color: '#cbd5e1'
              }}
            >
              {src}
            </span>
          ))}
        </div>

        {plan.event_risks?.length > 0 && (
          <div style={{ fontSize: '9.5px', color: 'var(--neon-amber)', fontFamily: 'var(--font-data)' }}>
            ⚠ Risks: {plan.event_risks.slice(0, 2).join(' · ')}
          </div>
        )}
      </div>

      {/* 7. Action Bar: Approve, Modify, Reject (Human-in-the-Loop) */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        borderTop: '1px solid rgba(255, 255, 255, 0.08)',
        paddingTop: '12px'
      }}>
        <div style={{ fontSize: '9.5px', color: 'var(--text-muted)', fontFamily: 'var(--font-data)' }}>
          Paper trading only. Gated human approval mandatory before any future PILOT execution.
        </div>

        <div style={{ display: 'flex', gap: '8px' }}>
          {onSendToChart && (
            <button
              onClick={() => onSendToChart(plan)}
              style={{
                background: 'rgba(0, 240, 255, 0.1)',
                border: '1px solid rgba(0, 240, 255, 0.4)',
                color: 'var(--neon-cyan)',
                fontFamily: 'var(--font-data)',
                fontSize: '10px',
                padding: '6px 12px',
                borderRadius: '3px',
                cursor: 'pointer'
              }}
            >
              📊 CHART LEVELS
            </button>
          )}

          {onModify && (
            <button
              onClick={() => onModify(plan)}
              style={{
                background: 'rgba(234, 179, 8, 0.15)',
                border: '1px solid var(--neon-amber)',
                color: 'var(--neon-amber)',
                fontFamily: 'var(--font-data)',
                fontSize: '10.5px',
                fontWeight: 700,
                padding: '6px 14px',
                borderRadius: '3px',
                cursor: 'pointer'
              }}
            >
              ✎ MODIFY PLAN
            </button>
          )}

          {onReject && (
            <button
              onClick={() => onReject(plan)}
              style={{
                background: 'rgba(239, 68, 68, 0.15)',
                border: '1px solid var(--neon-red)',
                color: 'var(--neon-red)',
                fontFamily: 'var(--font-data)',
                fontSize: '10.5px',
                fontWeight: 700,
                padding: '6px 14px',
                borderRadius: '3px',
                cursor: 'pointer'
              }}
            >
              ✕ REJECT
            </button>
          )}

          {onApprove && (
            <button
              disabled={isApproveDisabled}
              onClick={() => onApprove(plan)}
              title={isApproveDisabled ? 'Approve disabled: Sentinel verdict is VETO or pending' : 'Approve plan for paper trading'}
              style={{
                background: isApproveDisabled ? 'rgba(255, 255, 255, 0.05)' : 'rgba(34, 197, 94, 0.25)',
                border: `1px solid ${isApproveDisabled ? 'rgba(255, 255, 255, 0.15)' : 'var(--neon-green)'}`,
                color: isApproveDisabled ? '#64748b' : '#ffffff',
                fontFamily: 'var(--font-data)',
                fontSize: '11px',
                fontWeight: 800,
                padding: '6px 18px',
                borderRadius: '3px',
                cursor: isApproveDisabled ? 'not-allowed' : 'pointer',
                letterSpacing: '0.8px'
              }}
            >
              ✓ APPROVE FOR PAPER
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
